parameters.jsCode:
const body = $input.first().json.body;
const required = ['incident_title', 'incident_description', 'timeline', 'severity'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (!Array.isArray(body.timeline) || body.timeline.length < 2) return [{ json: { valid: false, error: 'timeline must be an array with at least 2 events' } }];
const severities = ['sev1', 'sev2', 'sev3', 'sev4'];
const severity = severities.includes(body.severity?.toLowerCase()) ? body.severity.toLowerCase() : 'sev2';
return [{ json: {
  valid: true,
  incidentId: body.incident_id || `INC-${Date.now()}`,
  incidentTitle: body.incident_title.trim(),
  severity,
  incidentDate: body.incident_date || new Date().toISOString().split('T')[0],
  incidentDescription: body.incident_description.trim().slice(0, 1500),
  timeline: body.timeline.map(e => ({ time: e.time || '', event: (e.event || '').slice(0, 300), actor: e.actor || '' })).slice(0, 30),
  rootCauseHypothesis: (body.root_cause_hypothesis || '').slice(0, 600),
  impactDescription: (body.impact_description || '').slice(0, 500),
  servicesAffected: Array.isArray(body.services_affected) ? body.services_affected : (body.services_affected || '').split(',').map(s=>s.trim()).filter(Boolean),
  detectionMethod: body.detection_method || '',
  resolutionSteps: Array.isArray(body.resolution_steps) ? body.resolution_steps : (body.resolution_steps || '').split('\n').map(s=>s.trim()).filter(Boolean),
  oncallEngineer: body.oncall_engineer || '',
  incidentCommander: body.incident_commander || '',
  postmortemAuthor: body.postmortem_author || '',
  teamEmail: body.team_email || '',
  replyEmail: body.reply_email || null
} }];

values.content:
Generate a postmortem for this incident.

Incident: {{ $json.incidentId }} — {{ $json.incidentTitle }}
Severity: {{ $json.severity.toUpperCase() }}
Date: {{ $json.incidentDate }}
On-call: {{ $json.oncallEngineer || 'not specified' }}
Incident commander: {{ $json.incidentCommander || 'not specified' }}
Services affected: {{ $json.servicesAffected.join(', ') || 'not specified' }}
Detected via: {{ $json.detectionMethod || 'not specified' }}

Incident description:
{{ $json.incidentDescription }}

Impact:
{{ $json.impactDescription || 'not specified' }}

Timeline:
{{ $json.timeline.map(e => e.time + (e.actor?' ['+e.actor+']':'') + ': ' + e.event).join('\n') }}

Root cause hypothesis:
{{ $json.rootCauseHypothesis || 'to be determined' }}

Resolution steps taken:
{{ $json.resolutionSteps.join('\n') || 'not specified' }}

Return this JSON:
{
  "executive_summary": "3-4 sentence summary for non-technical stakeholders: what happened, who was affected, how long, what was done",
  "what_happened": "narrative of the incident — chronological, explains the sequence of events and the technical context. 3-5 paragraphs.",
  "root_cause_analysis": {
    "immediate_cause": "the direct technical trigger",
    "contributing_factors": ["systemic factors that enabled or worsened the incident"],
    "why_not_caught_earlier": "why monitoring, tests, or processes didn't catch this before it became an incident"
  },
  "impact_assessment": {
    "duration_minutes": null,
    "users_affected": "description or estimate",
    "services_degraded": ["service and nature of degradation"],
    "data_loss": "yes/no/unknown with details",
    "financial_impact": "estimate or 'not assessed'"
  },
  "detection_and_response": "how the incident was detected and how the response unfolded — what went well, what was slow",
  "what_went_well": ["specific things the team did well during this incident"],
  "what_went_poorly": ["specific gaps in process, tooling, or response — blameless, systemic framing"],
  "action_items": [
    {
      "item": "specific, actionable improvement — not vague",
      "type": "prevention | detection | response | process",
      "priority": "P1 | P2 | P3",
      "owner": "team or role responsible",
      "due": "suggested timeframe e.g. within 2 weeks"
    }
  ],
  "lessons_learned": "2-3 sentences on what this incident teaches about the system or the team's practices"
}

