const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let pm;
try { pm = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
pm._meta = { incidentId: input.incidentId, incidentTitle: input.incidentTitle, severity: input.severity, incidentDate: input.incidentDate, oncallEngineer: input.oncallEngineer, incidentCommander: input.incidentCommander, postmortemAuthor: input.postmortemAuthor, timeline: input.timeline, teamEmail: input.teamEmail, replyEmail: input.replyEmail };
return [{ json: pm }];

const p = $input.first().json;
const m = p._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const sevColors = {sev1:'#dc2626',sev2:'#ea580c',sev3:'#d97706',sev4:'#2563eb'};
const sc = sevColors[m.severity] || '#6b7280';
const rca = p.root_cause_analysis || {};
const ia = p.impact_assessment || {};
const timelineRows = m.timeline.map(e => `<tr style="border-bottom:1px solid #f3f4f6"><td style="padding:7px 12px;font-size:12px;font-family:monospace;color:#6b7280;white-space:nowrap">${esc(e.time)}</td>${e.actor?`<td style="padding:7px 12px;font-size:12px;color:#9ca3af">${esc(e.actor)}</td>`:''}<td style="padding:7px 12px;font-size:13px">${esc(e.event)}</td></tr>`).join('');
const hasActor = m.timeline.some(e=>e.actor);
const actionRows = (p.action_items||[]).map(a => { const pc = {P1:'#dc2626',P2:'#d97706',P3:'#2563eb'}[a.priority]||'#6b7280'; const tc = {prevention:'#16a34a',detection:'#2563eb',response:'#d97706',process:'#7c3aed'}[a.type]||'#6b7280'; return `<tr style="border-bottom:1px solid #f3f4f6"><td style="padding:8px 12px;font-size:13px">${esc(a.item)}</td><td style="padding:8px 12px;text-align:center"><span style="background:${pc}22;color:${pc};font-size:11px;font-weight:700;padding:2px 7px;border-radius:8px">${esc(a.priority)}</span></td><td style="padding:8px 12px"><span style="background:${tc}22;color:${tc};font-size:11px;padding:2px 7px;border-radius:8px">${esc(a.type)}</span></td><td style="padding:8px 12px;font-size:12px;color:#6b7280">${esc(a.owner)}</td><td style="padding:8px 12px;font-size:12px;color:#6b7280">${esc(a.due)}</td></tr>`; }).join('');
const wentWell = (p.what_went_well||[]).map(w => `<div style="font-size:14px;padding:5px 0;border-bottom:1px solid #f0fdf4;color:#166534">✓ ${esc(w)}</div>`).join('');
const wentPoorly = (p.what_went_poorly||[]).map(w => `<div style="font-size:14px;padding:5px 0;border-bottom:1px solid #fff7ed;color:#92400e">→ ${esc(w)}</div>`).join('');
const contributing = (rca.contributing_factors||[]).map(f => `<li style="font-size:14px;margin-bottom:6px;line-height:1.5">${esc(f)}</li>`).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f5f0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:760px;margin:0 auto">
  <div style="background:#111827;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="display:flex;gap:10px;align-items:center;margin-bottom:6px">
      <span style="background:${sc};color:#fff;font-size:13px;font-weight:700;padding:4px 14px;border-radius:12px">${m.severity.toUpperCase()}</span>
      <span style="font-size:12px;color:#64748b">${esc(m.incidentId)} · ${esc(m.incidentDate)}</span>
    </div>
    <div style="font-size:19px;font-weight:700;line-height:1.3">${esc(m.incidentTitle)}</div>
    <div style="font-size:12px;color:#64748b;margin-top:4px">${m.oncallEngineer?'On-call: '+esc(m.oncallEngineer):''} ${m.incidentCommander?' · Commander: '+esc(m.incidentCommander):''} ${m.postmortemAuthor?' · Author: '+esc(m.postmortemAuthor):''}</div>
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Executive Summary</div>
    <p style="font-size:15px;line-height:1.75;color:#374151;margin:0">${esc(p.executive_summary)}</p>
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">What happened</div>
    <div style="font-size:14px;line-height:1.8;color:#374151;white-space:pre-line">${esc(p.what_happened)}</div>
  </div>
  <div style="background:#fff;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="background:#f9fafb"><th style="padding:8px 12px;font-size:11px;text-transform:uppercase;color:#9ca3af;text-align:left">Time</th>${hasActor?'<th style="padding:8px 12px;font-size:11px;text-transform:uppercase;color:#9ca3af;text-align:left">Actor</th>':''}<th style="padding:8px 12px;font-size:11px;text-transform:uppercase;color:#9ca3af;text-align:left">Event</th></tr></thead>
      <tbody>${timelineRows}</tbody>
    </table>
  </div>
  <div style="background:#fef2f2;padding:16px 28px;border:1px solid #fecaca">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:8px">Root Cause Analysis</div>
    <div style="font-size:14px;font-weight:600;margin-bottom:4px">Immediate cause:</div>
    <p style="font-size:14px;color:#374151;margin:0 0 10px">${esc(rca.immediate_cause)}</p>
    ${contributing?`<div style="font-size:14px;font-weight:600;margin-bottom:4px">Contributing factors:</div><ul style="padding-left:18px;margin:0 0 10px">${contributing}</ul>`:''}
    <div style="font-size:13px;color:#7f1d1d"><strong>Why not caught earlier:</strong> ${esc(rca.why_not_caught_earlier)}</div>
  </div>
  ${actionRows?`<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Action items</div>
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="background:#f9fafb;font-size:11px;text-transform:uppercase;color:#9ca3af"><th style="padding:7px 12px;text-align:left">Item</th><th style="padding:7px 12px">P</th><th style="padding:7px 12px">Type</th><th style="padding:7px 12px;text-align:left">Owner</th><th style="padding:7px 12px;text-align:left">Due</th></tr></thead>
      <tbody>${actionRows}</tbody>
    </table>
  </div>`:''}
  <div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">
      ${wentWell?`<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#16a34a;margin-bottom:7px">What went well</div>${wentWell}</div>`:''}
      ${wentPoorly?`<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#c2410c;margin-bottom:7px">What went poorly</div>${wentPoorly}</div>`:''}
    </div>
  </div>
  ${p.lessons_learned?`<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:5px">Lessons learned</div>
    <p style="font-size:14px;line-height:1.7;color:#374151;margin:0;font-style:italic">${esc(p.lessons_learned)}</p>
  </div>`:''}
  <div style="background:#111827;color:#475569;font-size:11px;padding:10px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">${esc(m.incidentId)} · ${esc(m.incidentTitle)} · Blameless postmortem</div>
</div></body></html>`;
return [{ json: { html, replyEmail: m.replyEmail, teamEmail: m.teamEmail, incidentId: m.incidentId, incidentTitle: m.incidentTitle, severity: m.severity, postmortem: p } }];
